    slug: "programmable-rna-trans-splicing-exon-replacement",
    title: { zh: "可编程 RNA 转剪接与外显子替换", en: "Programmable RNA Trans-Splicing for Exon Replacement" },
    qfocus: { zh: "在不改写 DNA 的前提下替换一整段外显子，能否压住顺式剪接的竞争与异常嵌合转录本？", en: "Replacing a whole exon without rewriting DNA — can competition from cis-splicing and aberrant chimeric transcripts be held down?" },
    domain: "生命",
    cluster: { code: "C52", zh: "RNA·表观与可编程医学", en: "RNA · Epigenetic & Programmable Medicine" },
    scores: [5, 4, 5, 2, 3, 3, 4, 4, 3],
    citation: {
      url: "https://doi.org/10.1016/j.cels.2025.101487",
      title: "Rewriting endogenous human transcripts with dual CRISPR-guided 3′ trans-splicing",
      venue: "Cell Systems",
      year: 2026,
    },
    brief: { zh: "用双 CRISPR 引导把转剪接分子拉到目标前体 mRNA 的 3′ 端，量化正确连接比例、完整异构体、蛋白与功能恢复，并逐项排查顺式剪接竞争、异常嵌合转录本、核内可达性与脱靶剪接。", en: "Use dual CRISPR guides to recruit the trans-splicing molecule to the 3′ end of a target pre-mRNA, quantify correct junction rate, full-length isoform, protein and functional restoration, and check item by item for cis-splicing competition, aberrant chimeric transcripts, nuclear accessibility and off-target splicing." },
    literature: [
      { title: "Phenotype correction of hemophilia A mice by spliceosome-mediated RNA trans-splicing", venue: "Nature Medicine", year: 2003, url: "https://doi.org/10.1038/nm900" },
      { title: "RNA exon editing: Splicing the way to treat human diseases", venue: "Molecular Therapy - Nucleic Acids", year: 2024, url: "https://doi.org/10.1016/j.omtn.2024.102311" },
    ],
    depth: {
      overview: { zh: "RNA 转剪接在转录本层替换较长外显子或插入编码序列，科学对象不同于单碱基 RNA 编辑：它改的是剪接产物而非某个碱基。Cell Systems 的双 CRISPR 引导 3′ 转剪接在人细胞中改写内源转录本，而 2003 年 Nature Medicine 早已用剪接体介导的转剪接校正血友病 A 小鼠表型。", en: "RNA trans-splicing replaces a sizeable exon or inserts coding sequence at the transcript level — a different scientific object from single-base RNA editing, since it changes the splice product rather than one base. Cell Systems' dual CRISPR-guided 3′ trans-splicing rewrites endogenous human transcripts, while Nature Medicine corrected the hemophilia A phenotype in mice by spliceosome-mediated trans-splicing back in 2003." },
      whyMatters: { zh: "一次替换一整段外显子能覆盖同一基因上的大量突变，且不改基因组、可随转录本周转而消退；但要在核内与顺式剪接抢同一条前体 mRNA，效率与保真度天然受制。", en: "Replacing an entire exon in one move can cover many mutations in the same gene, leaves the genome untouched, and fades as transcripts turn over; but it must win the same pre-mRNA away from cis-splicing inside the nucleus, which caps both efficiency and fidelity." },
      ifAnswered: { zh: "突变分散在多个外显子的遗传病可以按外显子而非按位点设计疗法，一条分子覆盖一整类患者。", en: "Genetic diseases whose mutations scatter across exons could be treated per exon rather than per site, with one molecule covering a whole class of patients." },
      approaches: [
        { zh: "用双 CRISPR 引导提高转剪接分子在目标前体 mRNA 上的核内停留与定位精度。", en: "Use dual CRISPR guides to improve nuclear residence and positioning of the trans-splicing molecule on the target pre-mRNA." },
        { zh: "以长读长测序区分正确连接、部分连接与异常嵌合转录本的实际比例。", en: "Use long-read sequencing to separate the real proportions of correct junctions, partial junctions and aberrant chimeric transcripts." },
        { zh: "在血友病 A 一类有明确功能读数的模型里，把蛋白活性恢复作为主要终点。", en: "In models with an unambiguous functional readout such as hemophilia A, make restored protein activity the primary endpoint." },
      ],
      barrier: { zh: "转剪接必须在核内与内源顺式剪接竞争同一条前体 mRNA，正确连接率一旦不高，剩下的就是难以清点的嵌合转录本。", en: "Trans-splicing must compete with endogenous cis-splicing for the same pre-mRNA inside the nucleus; once the correct-junction rate falls short, what remains is a population of chimeric transcripts that is hard to enumerate." },
      subQuestions: [
        { zh: "正确连接的比例需要达到多少，功能蛋白恢复才越过治疗阈值而非仅仅可检测？", en: "How high must the correct-junction fraction be for functional protein restoration to clear a therapeutic threshold rather than merely be detectable?" },
        { zh: "异常嵌合转录本在何种序列语境下富集，能否用剪接位点强度事先预测并回避？", en: "In what sequence contexts do aberrant chimeric transcripts accumulate, and can splice-site strength predict and avoid them in advance?" },
        { zh: "细胞与小鼠里成立的替换效率，能否在组织递送和核内可达性受限时保住？", en: "Does the replacement efficiency established in cells and mice survive once tissue delivery and nuclear accessibility become limiting?" },
      ],
    },
